WITH valid AS (SELECT id, customer_id, browser, started_at, country, CONCAT(device, ' ', browser) AS device_browser FROM sessions WHERE country IS NOT NULL AND browser IS DISTINCT FROM 'Firefox'), gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM valid), sessionized AS (SELECT id, customer_id, started_at, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, MIN(started_at) AS started_at, APPROX_PERCENTILE(island_id, ARRAY(0.25, 0.5, 0.75)) AS island_id_quartiles, ROUND(AVG(island_id), 2) AS avg_island_id, ROUND(AVG(island_id), 2) AS avg_island_id_2, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes FROM sessionized GROUP BY DATE_TRUNC('QUARTER', started_at) HAVING ROUND(AVG(island_id), 2) >= 0
